/// <summary>
/// Class to handle the inventory Dimension setup per item with support for license plating (or using location instead of licence plating)
/// </summary>
///
[ExtensionOf(classStr(TFMInventDimSetup))]
final class MobInventDimSetup_Extension
{
}

Method.Source:
/// <summary>
/// Method to validate whether the WMS Pallet dimension is active
/// </summary>
/// <returns>string, True if dimension is active, otherwise False.</returns>
public boolean registerWMSPallet()
{
    return next registerWMSPallet() && new MobDocLicensePlateOverview().parmEnableLicensePlating();
}

public boolean registerLicensePlate()
{
    return next registerLicensePlate() && new MobDocLicensePlateOverview().parmEnableLicensePlating();
}
